import type { HTMLAttributes } from "react";

type AlertVariant = "default" | "danger";
export function Alert({ className = "", variant = "default", ...props }: HTMLAttributes<HTMLDivElement> & { variant?: AlertVariant }) {
  const tone = variant === "danger" ? "co-border-black co-bg-black co-text-white" : "co-border-black/20 co-text-black";
  return <div role="alert" className={`co-relative co-w-full co-rounded-lg co-border co-bg-white co-p-4 ${tone} ${className}`.trim()} {...props} />;
}
export function AlertTitle({ className = "", ...props }: HTMLAttributes<HTMLHeadingElement>) { return <h5 className={`co-mb-1 co-font-medium co-leading-none ${className}`.trim()} {...props} />; }
export function AlertDescription({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-text-sm co-leading-relaxed co-opacity-70 ${className}`.trim()} {...props} />; }
